188	/*--------------------*/
189	char   *
190	getop(expr, oper)
191	  char   *expr;
192	  char   *oper;
193	{
194	  char    ch;
195	  switch (ch = *(expr++)) {
196	  case '&':
197	    if (*(expr++) == '&')
198	      *oper = AND;
199	    break;
200	  case '|':
201	    if (*(expr++) == '|')
202	      *oper = OR;
203	    break;
204	  case '=':
205	    if (*(expr++) == '=')
206	      *oper = EQUAL;
207	    break;
208	  case '!':
209	    if (*(expr++) == '=')
210	      *oper = NEQU;
211	    break;
212	  case '<':
213	    if (*expr == '=') {
214	      ++expr;
215	      *oper = LTE;
216	    } else
217	      *oper = '<';
218	    break;
219	  case '>':
220	    if (*expr == '=') {
221	      ++expr;
222	      *oper = GTE;
223	    } else
224	      *oper = '>';
225	    break;
226	  default:
227	    *oper = ch;
228	    break;
229	  }
230	  return expr;
231	}
232	/*--------------------*/
233	char   *
234	getreg(expr, regId, val)
235	  char   *expr;
236	  int     regId;
237	  long   *val;
238	{
239	  SKIP_SPACE(expr);
240	  if (*expr == '=' && *(expr + 1) != '=') {        /* assignment, not equality */
241	    expr = eval(-1, 0L, IDENT, expr + 1, val);
242	    regAr[regId] = *val;
243	  } else
244	    *val = regAr[regId];
245	  return expr;
246	}
247	
248	/*--------------------*/
249	char   *
250	getval(expr, val)
251	  char   *expr;
252	  long   *val;
253	{
254	  char    buffer[BIGNUM];
255	  int     regId;
256	  int     bufptr = 0;
257	  long    accum;
258	
259	  SKIP_SPACE(expr);
260	  if (*expr == '(') {                /* parenthetical expression */
261	    expr = eval(-1, 0L, IDENT, expr + 1, val);
262	    if (*expr != ')')
263	      evalerr = BAD_EXPR;
264	    return expr + 1;
265	  }
266	  if (*expr == '-') {                /* unary minus */
267	    expr = getval(expr + 1, &accum);
268	    *val = accum * -1;
269	    return expr;
270	  } else if (*expr == '!') {        /* logical NOT */
271	    expr = getval(expr + 1, &accum);
272	    *val = (accum ? 0 : 1);
273	    return expr;
274	  } else if (*expr == '+')        /* unary plus */
275	    return getval(expr + 1, val);
276	  else if (((regId = (int) toupper(*expr)) >= 'A') && (regId <= 'Z'))
277	    return getreg(expr + 1, regId - 'A', val);
278	  else
279	    while (isdigit(*expr) && bufptr < BIGNUM) /* FIXED (?): possible buffer overflow without the bufptr < BIGNUM? */
280	      buffer[bufptr++] = *expr++;
281	  if (bufptr == 0)
282	    evalerr = BAD_EXPR;                /* no digits */
283	  buffer[bufptr] = 0;
284	  sscanf(buffer, "%ld", val); /* FIXME wouldn't it be simpler and more efficient to calculate val directly, ie val = val*10+digitvalueof(*expr++) in the loop? */
285	  return expr;
286	}
