288	/*--------------------*/
289	#ifdef NEW_STYLE
290	char   *
291	eval(int prevPrec, long val1, char oper1, char *expr, long *result)
292	#else
293	char   *
294	eval(prevPrec, val1, oper1, expr, result)
295	  int     prevPrec;/* prevPrec is the precedence that ends the subevaluation, ie in 1 && 2+3*4-1 || 0 prevPrec would be prec of && while evaluating 2+3*4-1 */
296	  char    oper1, *expr;
297	  long    val1, *result;
298	#endif
299	{
300	  long    result2, val2;
301	  char    oper2;
302	  int     prec1, prec2;
303	
304	#ifdef DEBUG
305	      fprintf(stderr, "eval prev = %ld, val1 = %ld, op1 = %c \n", prevPrec, val1, X(oper1));
306	#endif
307	
308	  saveOper = 0;
309	
310	  expr = getval(expr, &val2);
311	  SKIP_SPACE(expr);
312	  if (TERMINAL(*expr)) {        /* trivial: expr is number or () */
313	    *result = calc(val1, val2, oper1);
314	    return expr;
315	  }
316	  expr = getop(expr, &oper2);
317	
318	  if ((prec1 = PRECEDENCE(oper1)) >= (prec2 = PRECEDENCE(oper2))) {
319	    if (prec2 > prevPrec /* don't understand this, so I removed it: || prec1 <= prevPrec */) {
320	      /* continue to gobble up expressions */
321	
322	#ifdef DEBUG
323	      fprintf(stderr, "gobble prev = %ld, val1 = %ld, op1 = %c, val2 = %ld, op2 = %c \n", prevPrec, val1, X(oper1), val2, X(oper2));
324	#endif
325	
326	      expr = eval(prevPrec, calc(val1, val2, oper1), oper2, expr, result);/* prec1 -> prevPrec */
327	
328	#ifdef DEBUG
329	      fprintf(stderr, "gobbled (prev %ld) %ld = ((%ld %c %ld) %c ..)\n", prevPrec, *result, val1, X(oper1), val2, X(oper2));
330	#endif
331	
332	    } else {
333	      /* return from subevaluation of terms with higher precedence */
334	      *result = calc(val1, val2, oper1);
335	      saveOper = oper2;/* akin to "push back" in parsers */
336	
337	#ifdef DEBUG
338	      fprintf(stderr, "return (prev %ld, save = %c) %ld = (%ld %c %ld)\n", prevPrec, X(saveOper), *result, val1, X(oper1), val2);
339	#endif
340	
341	    }
342	  } else {
343	
344	#ifdef DEBUG
345	      fprintf(stderr, "subevaluate op2, prev = %ld, val1 = %ld, op1 = %c, val2 = %ld, op2 = %c, saveOp = %c (%ld) \n", prevPrec, val1, X(oper1), val2, X(oper2), X(saveOper), saveOper);
346	#endif
347	
348	    expr = eval(prec1, val2, oper2, expr, &result2);/* start subevaluation starting from val2 op2 */
349	    *result = calc(val1, result2, oper1);
350	
351	#ifdef DEBUG
352	      fprintf(stderr, "returned from subeval, result2 = %ld, result = %ld, prev = %ld, val1 = %ld, op1 = %c, val2 = %ld, op2 = %c, saveOp = %c (%ld) \n", result2, *result, prevPrec, val1, X(oper1), val2, X(oper2), X(saveOper), saveOper);
353	#endif
354	
355	      if (saveOper && PRECEDENCE(saveOper) >= prevPrec) {/* otherwise (if saveOper, but precedence < prevPrec) yet more nested subevalutions to return from */
356	
357	#ifdef DEBUG
358	      fprintf(stderr, "evaluate saveOper, prev = %ld, val1 = %ld, op1 = %c \n", prevPrec, *result , X(saveOper));
359	#endif
360	
361	      expr = eval(prevPrec, *result, saveOper, expr, result);/* prec2 -> prevPrec */
362	
363	#ifdef DEBUG
364	      fprintf(stderr, "return, no more subevals (prev %ld, old Saved: %c (%ld)) %ld = .. ? (%ld %c (%ld %c ..))\n", prevPrec, X(saveOper), saveOper, *result,
365	              val1, X(oper1), val2, X(oper2));
366	#endif
367	
368	      /* saveOper = 0; */ /* FIXED don't erase history, continue if saveOper exists */
369	    }
370	
371	#ifdef DEBUG
372	    else
373	      fprintf(stderr, "return, no saveOp or more subevals (prev %ld, saveOp = %c (%ld)) %ld = (%ld %c (%ld %c ..))\n", prevPrec, X(saveOper), saveOper, *result, val1, X(oper1), val2, X(oper2));
374	#endif
375	
376	  }
377	
378	  return expr;
379	}
